package rules; import core.CidrBlock;import core.IpAddress; public final class AddressExpression{private final String raw;public AddressExpression(String raw){this.raw=raw==null?"any":raw.trim();}public boolean matches(IpAddress ip){if(raw.equals("any")||raw.equals("$HOME_NET")||raw.equals("$EXTERNAL_NET"))return true;try{return CidrBlock.parse(raw).contains(ip);}catch(Exception ignored){}try{return IpAddress.parse(raw).equals(ip);}catch(Exception ignored){}return false;}public String raw(){return raw;}public String normalized(){return raw.toLowerCase(java.util.Locale.ROOT);}}
